const PACKED_ASSETS = {"./figurer/nila.webp": "data:image/webp;base64,", "./figurer/norin.webp": "data:image/webp;base64,", "./konst/sprites.webp": "data:image/webp;base64,", "./konst/back.webp": "data:image/webp;base64,", "./konst/bageri.webp": "data:image/webp;base64,", "./konst/borggard.webp": "data:image/webp;base64,", "./konst/glanta.webp": "data:image/webp;base64,", "./konst/himmel.webp": "data:image/webp;base64,", "./konst/karta.webp": "data:image/webp;base64,", "./konst/natt.webp": "data:image/webp;base64,", "./konst/skog.webp": "data:image/webp;base64,", "./konst/stuga.webp": "data:image/webp;base64,", "./konst/tradgard.webp": "data:image/webp;base64,"};

import { Ljudmotor } from '../delat/ljudmotor.js';

export const TAU = Math.PI * 2;
export const EXPR = ['glad', 'skratt', 'forvanad', 'busig', 'modig', 'fundersam', 'ledsen'];
export const EXPR_FRAME = {
  glad: 'glad', skratt: 'skratt', forvanad: 'forvanad',
  busig: 'vinkar', modig: 'glad', fundersam: 'forvanad', ledsen: 'forvanad',
};

export const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
export const lerp = (a, b, t) => a + (b - a) * t;
export const dist = (ax, ay, bx, by) => Math.hypot(bx - ax, by - ay);
export const easeOutBack = (t) => {
  const c1 = 1.70158, c3 = c1 + 1;
  return 1 + c3 * Math.pow(t - 1, 3) + c1 * Math.pow(t - 1, 2);
};

/* ---------- Spara / ladda framsteg ---------- */
const SAVE_KEY = 'nila_norin_v2_save';
export const save = {
  sister: 'nila',
  unlocked: 0,
  unlockAll: false,
  stars: {},
  muted: false,
  load() {
    try {
      const raw = JSON.parse(localStorage.getItem(SAVE_KEY) || 'null');
      if (raw && typeof raw === 'object') {
        if (raw.sister === 'nila' || raw.sister === 'norin') this.sister = raw.sister;
        if (typeof raw.unlocked === 'number') this.unlocked = clamp(raw.unlocked, 0, 20);
        if (typeof raw.unlockAll === 'boolean') this.unlockAll = raw.unlockAll;
        if (raw.stars && typeof raw.stars === 'object') this.stars = { ...raw.stars };
        if (typeof raw.muted === 'boolean') this.muted = raw.muted;
      }
    } catch {}
  },
  write() {
    try {
      localStorage.setItem(SAVE_KEY, JSON.stringify({
        sister: this.sister,
        unlocked: this.unlocked,
        unlockAll: this.unlockAll,
        stars: this.stars,
        muted: this.muted,
      }));
    } catch {}
  },
  reset() {
    this.unlocked = 0;
    this.unlockAll = false;
    this.stars = {};
    this.write();
  },
  totalStars() {
    return Object.values(this.stars).reduce((s, n) => s + (Number(n) || 0), 0);
  },
};
save.load();

/* ---------- Ljud + mjuk xylofon för musik- & stjärnbanor ---------- */
export const ljud = new Ljudmotor({ storageKey: 'nila_norin_v2_ljud', basUrl: '' });
let bankReady = false;
let bankPromise = null;

export function ensureAudio() {
  ljud.unlock();
  if (!bankPromise) {
    bankPromise = fetch('./ljud/bank.json')
      .then((r) => r.json())
      .then((json) => {
        const b = json.banker || {};
        const keys = ['tap', 'ok', 'pling', 'star', 'jump', 'land', 'step', 'pop', 'softno', 'cheer', 'heart', 'open', 'whoosh', 'plant', 'water'];
        return Promise.all(keys.map((k) => b[k]
          ? ljud.loadBank(k, b[k].map((f) => ({ ogg: (typeof f.ogg === 'string' && f.ogg.startsWith('data:') ? f.ogg : ljud.basUrl + f.ogg), m4a: (typeof f.m4a === 'string' && f.m4a.startsWith('data:') ? f.m4a : ljud.basUrl + f.m4a) })))
          : Promise.resolve()));
      })
      .then(() => { bankReady = true; })
      .catch(() => {});
  }
}

export function playSfx(name, opts) {
  if (save.muted) return;
  if (!ljud.upplast) ljud.unlock();
  if (bankReady) {
    ljud.play(name, { buss: name === 'tap' ? 'ui' : 'sfx', ...(opts || {}) });
  }
}

const PENT = [523.25, 587.33, 659.25, 783.99, 880.0, 1046.5];
export function playNote(idx, dur = 0.38) {
  if (save.muted) return;
  ljud.unlock();
  const ctx = ljud.ctx;
  if (!ctx || ctx.state !== 'running') return;
  const now = ctx.currentTime;
  const f = PENT[((idx % PENT.length) + PENT.length) % PENT.length];
  const osc = ctx.createOscillator();
  const osc2 = ctx.createOscillator();
  const g = ctx.createGain();
  osc.type = 'sine';
  osc2.type = 'triangle';
  osc.frequency.setValueAtTime(f, now);
  osc2.frequency.setValueAtTime(f * 2, now);
  g.gain.setValueAtTime(0.001, now);
  g.gain.exponentialRampToValueAtTime(0.16, now + 0.015);
  g.gain.exponentialRampToValueAtTime(0.0008, now + dur);
  const g2 = ctx.createGain();
  g2.gain.value = 0.14;
  osc.connect(g);
  osc2.connect(g2);
  g2.connect(g);
  g.connect(ljud.noder?.bussar?.sfx || ctx.destination);
  osc.start(now);
  osc2.start(now);
  osc.stop(now + dur + 0.03);
  osc2.stop(now + dur + 0.03);
}

/* ---------- Bilder, figurark & bakgrunder ---------- */
export const SLOT = {
  nila: { img: null, ok: false, keyed: null },
  norin: { img: null, ok: false, keyed: null },
};
const BGS = {};
let atlasImg = null;
let atlasMap = null;

function loadImage(src) {
  return new Promise((res) => {
    const im = new Image();
    im.onload = () => res(im);
    im.onerror = () => res(null);
    im.src = PACKED_ASSETS[src] || src;
  });
}

export function keyedSheet(slot) {
  if (!slot.img) return null;
  if (slot.keyed) return slot.keyed;
  const w = slot.img.width, h = slot.img.height;
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  const g = c.getContext('2d');
  g.drawImage(slot.img, 0, 0);
  const im = g.getImageData(0, 0, w, h);
  const d = im.data;
  for (let i = 0; i < d.length; i += 4) {
    const r = d[i], gv = d[i + 1], b = d[i + 2];
    if (r > 200 && b > 140 && gv < 80 && (r - gv) > 80) {
      const m = Math.min(r, b) - gv;
      d[i + 3] = m > 140 ? 0 : Math.min(d[i + 3], Math.max(0, 255 - m * 2));
    }
  }
  g.putImageData(im, 0, 0);
  slot.keyed = c;
  return c;
}

export async function loadCoreAssets() {
  const [nila, norin, spImg, spJson, karta] = await Promise.all([
    loadImage('./figurer/nila.webp'),
    loadImage('./figurer/norin.webp'),
    loadImage('./konst/sprites.webp'),
    fetch('./konst/sprites.json').then((r) => r.json()).catch(() => null),
    loadBg('karta'),
  ]);
  if (nila) { SLOT.nila.img = nila; SLOT.nila.ok = true; keyedSheet(SLOT.nila); }
  if (norin) { SLOT.norin.img = norin; SLOT.norin.ok = true; keyedSheet(SLOT.norin); }
  atlasImg = spImg;
  atlasMap = spJson;
  return karta;
}

export async function loadBg(name) {
  if (BGS[name]) return BGS[name];
  const im = await loadImage(`./konst/${name}.webp`);
  if (im) BGS[name] = im;
  return im;
}

export function getBg(name) {
  return BGS[name] || null;
}

export function blit(ctx, name, x, y, opt = {}) {
  if (!atlasImg || !atlasMap || !atlasMap[name]) return false;
  const r = atlasMap[name];
  const s = opt.scale || 1;
  const h = (opt.h || r.h) * s;
  const w = h * (r.w / r.h);
  ctx.save();
  ctx.translate(x + (opt.dx || 0), y + (opt.bob || 0));
  if (opt.rot) ctx.rotate(opt.rot);
  ctx.scale((opt.face || 1) * (opt.sx || 1), opt.sy || 1);
  if (opt.alpha !== undefined) ctx.globalAlpha = opt.alpha;
  ctx.drawImage(atlasImg, r.x, r.y, r.w, r.h, -w / 2, -h, w, h);
  ctx.restore();
  return true;
}

/* ---------- Exakta Nila & Norin-figurer + glädjedans ---------- */
export function gladjedans(t) {
  const cyc = ((t % 2.4) + 2.4) % 2.4;
  const d = { pose: 'cheer', expr: 'skratt', sx: 1, sy: 1, bob: 0, rot: 0, dx: 0 };
  if (cyc < 0.2) { d.pose = 'land'; d.sy = 0.84; d.sx = 1.16; }
  else if (cyc < 0.55) {
    const k = (cyc - 0.2) / 0.35;
    d.pose = 'jump'; d.expr = 'skratt'; d.bob = -42 * Math.sin(k * Math.PI); d.sy = 1.1; d.sx = 0.9;
  } else if (cyc < 1.3) {
    d.pose = 'dans'; d.expr = 'skratt'; d.bob = -4 + Math.sin(t * 16) * 6; d.rot = Math.sin(t * 7) * 0.16;
  } else {
    d.pose = 'cheer'; d.expr = 'busig'; d.dx = Math.sin((cyc - 1.3) * 9) * 18;
    d.bob = -Math.abs(Math.sin((cyc - 1.3) * 9)) * 16;
  }
  return d;
}

export function drawShadow(ctx, x, y, rx, ry, alpha = 0.22) {
  ctx.save();
  ctx.fillStyle = `rgba(38,26,14,${alpha})`;
  ctx.beginPath();
  ctx.ellipse(x, y, rx, ry, 0, 0, TAU);
  ctx.fill();
  ctx.restore();
}

export function drawHero(ctx, T, x, y, opt = {}) {
  const who = opt.who || save.sister || 'nila';
  const expr = opt.expr || 'glad';
  const pose = opt.pose || 'idle';
  const scale = (opt.scale || 1) * (who === 'nila' ? 0.96 : 1);
  let sx = opt.sx || 1, sy = opt.sy || 1;
  const breath = 1 + Math.sin(T * 2.5) * 0.03;
  if (pose === 'idle' || pose === 'cheer') { sy *= breath; sx *= 2 - breath; }
  if (pose === 'jump') { sy *= 1.1; sx *= 0.9; }
  if (pose === 'land') { sy *= 0.86; sx *= 1.14; }
  let bob = 0;
  if (pose === 'walk') bob = -Math.abs(Math.sin((opt.phase || 0) * TAU)) * 7;
  if (pose === 'cheer') bob = -2 + Math.sin(T * 8) * 3;
  if (pose === 'jump') bob = -4;
  if (pose === 'dans') bob = -6 + Math.sin(T * 14) * 5;
  bob += opt.bob || 0;
  const x2 = x + (opt.dx || 0);
  drawShadow(ctx, x2, y + 2, 20 * scale * sx, 6 * scale);
  const slot = SLOT[who];
  if (slot && slot.ok && slot.img) {
    const iw = slot.img.width, ih = slot.img.height, fw = iw / 7, fh = ih;
    const idx = Math.max(0, EXPR.indexOf(expr));
    const dw = 86 * scale, dh = 86 * scale * (fh / fw);
    ctx.save();
    ctx.translate(x2, y);
    if (opt.rot) ctx.rotate(opt.rot);
    ctx.scale((opt.face || 1) * sx, sy);
    ctx.drawImage(keyedSheet(slot), idx * fw, 0, fw, fh, -dw / 2, -dh + bob, dw, dh);
    ctx.restore();
    return;
  }
  const fr = EXPR_FRAME[expr] || 'glad';
  blit(ctx, `${who}-${fr}`, x2, y, { scale, h: 112, face: opt.face || 1, sx, sy, bob, rot: opt.rot });
}

export function drawPortrait(canvas, who) {
  const slot = SLOT[who];
  const c = canvas.getContext('2d');
  c.clearRect(0, 0, canvas.width, canvas.height);
  if (!slot || !slot.ok || !slot.img) return;
  const sheet = keyedSheet(slot);
  const fw = slot.img.width / 7, fh = slot.img.height;
  c.drawImage(sheet, 0, 0, fw, fh * 0.65, 2, 2, canvas.width - 4, canvas.height - 4);
}

/* ---------- Akvarellbakgrund + säker spelyta ---------- */
export function drawBgPlate(ctx, W, H, bgName, tint = '#d9ccb2') {
  ctx.fillStyle = tint;
  ctx.fillRect(0, 0, W, H);
  const bg = getBg(bgName);
  if (!bg) return { x: 0, y: 0, w: W, h: H };
  const s = Math.max(W / bg.width, H / bg.height);
  const dw = bg.width * s, dh = bg.height * s;
  const dx = (W - dw) / 2, dy = (H - dh) / 2;
  ctx.drawImage(bg, dx, dy, dw, dh);
  return { x: dx, y: dy, w: dw, h: dh };
}

export function getPlayRect(W, H) {
  const compact = Math.min(W, H) < 460;
  const top = compact ? 64 : 74;
  const bottom = compact ? 70 : 78;
  const side = compact ? 22 : 34;
  return { x: side, y: top, w: Math.max(120, W - side * 2), h: Math.max(120, H - top - bottom) };
}

/* ---------- Poolade partiklar (stjärnor, hjärtan, bubblor, löv, konfetti) ---------- */
export class JuiceParticles {
  constructor(max = 220) {
    this.pool = Array.from({ length: max }, () => ({
      alive: false, kind: 'dot', x: 0, y: 0, vx: 0, vy: 0, g: 120,
      life: 0, max: 1, r: 5, rot: 0, vr: 0, color: '#ffe17a',
    }));
  }
  _alloc() {
    for (let i = 0; i < this.pool.length; i++) if (!this.pool[i].alive) return this.pool[i];
    return null;
  }
  burst(x, y, n = 14, opts = {}) {
    const colors = opts.colors || ['#ffe17a', '#ff9db7', '#9be2b6', '#8cd4ff'];
    for (let i = 0; i < n; i++) {
      const p = this._alloc();
      if (!p) return;
      const a = (TAU * i) / n + (Math.random() - 0.5) * 0.5;
      const sp = (opts.speed || 120) * (0.45 + Math.random() * 0.75);
      p.alive = true;
      p.kind = opts.kind || (i % 3 === 0 ? 'star' : 'dot');
      p.x = x; p.y = y;
      p.vx = Math.cos(a) * sp;
      p.vy = Math.sin(a) * sp - (opts.lift || 45);
      p.g = opts.g !== undefined ? opts.g : 140;
      p.life = (opts.life || 0.75) * (0.7 + Math.random() * 0.5);
      p.max = p.life;
      p.r = (opts.r || 6) * (0.7 + Math.random() * 0.6);
      p.rot = Math.random() * TAU;
      p.vr = (Math.random() - 0.5) * 6;
      p.color = colors[i % colors.length];
    }
  }
  clear() {
    for (const p of this.pool) p.alive = false;
  }
  confetti(W, H, n = 42) {
    const colors = ['#f7c654', '#f2829b', '#7bc8e8', '#8ad190', '#c99ef2'];
    for (let i = 0; i < n; i++) {
      const p = this._alloc();
      if (!p) return;
      p.alive = true;
      p.kind = 'confetti';
      p.x = Math.random() * W;
      p.y = -10 - Math.random() * 40;
      p.vx = (Math.random() - 0.5) * 90;
      p.vy = 60 + Math.random() * 110;
      p.g = 35;
      p.life = 2.2 + Math.random() * 1.1;
      p.max = p.life;
      p.r = 5 + Math.random() * 4;
      p.rot = Math.random() * TAU;
      p.vr = (Math.random() - 0.5) * 8;
      p.color = colors[i % colors.length];
    }
  }
  update(dt) {
    for (let i = 0; i < this.pool.length; i++) {
      const p = this.pool[i];
      if (!p.alive) continue;
      p.life -= dt;
      if (p.life <= 0) { p.alive = false; continue; }
      p.vy += p.g * dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.rot += p.vr * dt;
    }
  }
  draw(ctx) {
    for (let i = 0; i < this.pool.length; i++) {
      const p = this.pool[i];
      if (!p.alive) continue;
      const a = clamp(p.life / p.max, 0, 1);
      ctx.save();
      ctx.globalAlpha = a;
      ctx.translate(p.x, p.y);
      ctx.rotate(p.rot);
      ctx.fillStyle = p.color;
      if (p.kind === 'heart') {
        drawHeartPath(ctx, p.r * 0.9);
        ctx.fill();
      } else if (p.kind === 'star') {
        drawStarPath(ctx, 5, p.r, p.r * 0.45);
        ctx.fill();
      } else if (p.kind === 'confetti') {
        ctx.fillRect(-p.r, -p.r * 0.5, p.r * 2, p.r);
      } else {
        ctx.beginPath();
        ctx.arc(0, 0, p.r * 0.65, 0, TAU);
        ctx.fill();
      }
      ctx.restore();
    }
  }
}

/* ---------- Akvarell-penslar & återanvändbara former ---------- */
export function drawHeartPath(ctx, s) {
  ctx.beginPath();
  ctx.moveTo(0, s * 0.4);
  ctx.bezierCurveTo(-s * 1.1, -s * 0.35, -s * 0.7, -s * 1.25, 0, -s * 0.45);
  ctx.bezierCurveTo(s * 0.7, -s * 1.25, s * 1.1, -s * 0.35, 0, s * 0.4);
}

export function drawStarPath(ctx, pts, outer, inner) {
  ctx.beginPath();
  for (let i = 0; i < pts * 2; i++) {
    const r = i % 2 === 0 ? outer : inner;
    const a = (i * Math.PI) / pts - Math.PI / 2;
    const px = Math.cos(a) * r, py = Math.sin(a) * r;
    if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
  }
  ctx.closePath();
}

export function drawGlowRing(ctx, T, x, y, r, color = 'rgba(255, 214, 102, 0.7)') {
  const pulse = 1 + Math.sin(T * 4.5) * 0.08;
  ctx.save();
  ctx.strokeStyle = color;
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(x, y, r * pulse, 0, TAU);
  ctx.stroke();
  const g = ctx.createRadialGradient(x, y, r * 0.2, x, y, r * 1.35 * pulse);
  g.addColorStop(0, 'rgba(255, 232, 148, 0.28)');
  g.addColorStop(1, 'rgba(255, 232, 148, 0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(x, y, r * 1.35 * pulse, 0, TAU);
  ctx.fill();
  ctx.restore();
}

export function drawGuideHand(ctx, T, ax, ay, bx, by) {
  const hasEnd = bx !== undefined && by !== undefined;
  const k = hasEnd ? (Math.sin(T * 2.2 - 0.6) + 1) * 0.5 : 0;
  const arc = hasEnd ? -Math.sin(k * Math.PI) * 26 : Math.sin(T * 4.2) * 8;
  const hx = hasEnd ? lerp(ax, bx, k) : ax;
  const hy = hasEnd ? lerp(ay, by, k) + arc : ay + arc;
  if (hasEnd) {
    ctx.save();
    ctx.strokeStyle = 'rgba(255, 234, 148, 0.72)';
    ctx.lineWidth = 4;
    ctx.setLineDash([8, 9]);
    ctx.lineDashOffset = -T * 32;
    ctx.beginPath();
    ctx.moveTo(ax, ay);
    ctx.quadraticCurveTo((ax + bx) / 2, Math.min(ay, by) - 34, bx, by);
    ctx.stroke();
    ctx.restore();
  }
  ctx.save();
  ctx.translate(hx + 6, hy + 12);
  ctx.rotate(-0.22);
  ctx.fillStyle = 'rgba(38, 25, 12, 0.2)';
  ctx.beginPath();
  ctx.ellipse(2, 6, 13, 15, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#fff5e4';
  ctx.strokeStyle = '#6f4c2b';
  ctx.lineWidth = 2.4;
  ctx.beginPath();
  ctx.roundRect(-9, -4, 18, 22, 9);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.roundRect(-4, -20, 8, 20, 4);
  ctx.fill();
  ctx.stroke();
  ctx.restore();
}

export function drawWatercolorBubble(ctx, T, x, y, r, hueColor = '#9bdfff') {
  ctx.save();
  const wob = 1 + Math.sin(T * 4 + x * 0.05) * 0.04;
  ctx.translate(x, y);
  ctx.scale(wob, 2 - wob);
  const g = ctx.createRadialGradient(-r * 0.28, -r * 0.3, r * 0.1, 0, 0, r);
  g.addColorStop(0, 'rgba(255,255,255,0.65)');
  g.addColorStop(0.55, hueColor + '55');
  g.addColorStop(0.92, hueColor + '99');
  g.addColorStop(1, 'rgba(255,255,255,0.85)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(0, 0, r, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(255,255,255,0.82)';
  ctx.lineWidth = 2;
  ctx.stroke();
  ctx.fillStyle = 'rgba(255,255,255,0.78)';
  ctx.beginPath();
  ctx.ellipse(-r * 0.34, -r * 0.34, r * 0.22, r * 0.12, -0.6, 0, TAU);
  ctx.fill();
  ctx.restore();
}

export function drawMushroom(ctx, x, y, r, color, squash = 0) {
  ctx.save();
  ctx.translate(x, y);
  const sy = 1 - squash * 0.28, sx = 1 + squash * 0.24;
  ctx.scale(sx, sy);
  drawShadow(ctx, 0, 2, r * 0.72, r * 0.22);
  ctx.fillStyle = '#f5ead3';
  ctx.strokeStyle = '#6c5137';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.roundRect(-r * 0.32, -r * 0.85, r * 0.64, r * 0.88, 8);
  ctx.fill();
  ctx.stroke();
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.ellipse(0, -r * 0.85, r, r * 0.66, 0, Math.PI, TAU);
  ctx.closePath();
  ctx.fill();
  ctx.stroke();
  ctx.fillStyle = '#fff9eb';
  for (const [dx, dy, dr] of [[-0.42, -1.1, 0.14], [0.22, -1.22, 0.16], [0.48, -0.98, 0.11]]) {
    ctx.beginPath();
    ctx.arc(dx * r, dy * r, dr * r, 0, TAU);
    ctx.fill();
  }
  ctx.restore();
}

export function drawBasket(ctx, x, y, r, color, iconFn) {
  ctx.save();
  ctx.translate(x, y);
  drawShadow(ctx, 0, r * 0.45, r * 0.9, r * 0.25);
  ctx.fillStyle = '#d5a86b';
  ctx.strokeStyle = '#6e4b26';
  ctx.lineWidth = 2.4;
  ctx.beginPath();
  ctx.moveTo(-r * 0.9, -r * 0.2);
  ctx.lineTo(r * 0.9, -r * 0.2);
  ctx.quadraticCurveTo(r * 0.78, r * 0.55, 0, r * 0.55);
  ctx.quadraticCurveTo(-r * 0.78, r * 0.55, -r * 0.9, -r * 0.2);
  ctx.closePath();
  ctx.fill();
  ctx.stroke();
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.roundRect(-r * 0.96, -r * 0.34, r * 1.92, r * 0.26, 8);
  ctx.fill();
  ctx.stroke();
  if (iconFn) iconFn(ctx, 0, r * 0.16, r * 0.34);
  ctx.restore();
}

export function drawWateringCan(ctx, x, y, tilt = 0, pouring = false, T = 0) {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(tilt);
  ctx.fillStyle = '#6fb8d6';
  ctx.strokeStyle = '#385d72';
  ctx.lineWidth = 2.4;
  ctx.beginPath();
  ctx.roundRect(-24, -18, 44, 34, 9);
  ctx.fill();
  ctx.stroke();
  // pip
  ctx.beginPath();
  ctx.moveTo(-22, -4);
  ctx.lineTo(-42, -20);
  ctx.lineTo(-38, -26);
  ctx.lineTo(-18, -12);
  ctx.closePath();
  ctx.fill();
  ctx.stroke();
  // handtag
  ctx.beginPath();
  ctx.arc(20, -2, 13, -Math.PI * 0.6, Math.PI * 0.6);
  ctx.stroke();
  if (pouring) {
    ctx.strokeStyle = 'rgba(130, 218, 255, 0.85)';
    ctx.lineWidth = 3;
    for (let i = 0; i < 4; i++) {
      const off = ((T * 30 + i * 8) % 24);
      ctx.beginPath();
      ctx.moveTo(-42 - i * 3, -20 + off * 0.8);
      ctx.lineTo(-48 - i * 4, -10 + off);
      ctx.stroke();
    }
  }
  ctx.restore();
}
